// M3KI - Nachrecherche fuer Initiativbewerbungen bei Agenturen.
// Ergaenzt AUSSCHLIESSLICH fehlende Informationen.
// M3B-Ergebnisse sind unantastbar.
//
// NORMALBETRIEB:
// TEST_LIMIT = 0
// TEST_STELLEN_ID = ''

const TEST_LIMIT = 0;
const TEST_STELLEN_ID = '';

function c(v) {
  return String(
    v === null || v === undefined ? '' : v
  )
    .replace(/\u00a0/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function clip(v, n) {
  return c(v).slice(0, n);
}

function wahr(v) {
  const s = c(v).toLowerCase();

  return (
    s === 'true' ||
    s === 'wahr' ||
    s === 'ja' ||
    s === '1'
  );
}

// M3B speichert beispielsweise:
// bewerbung@example.com (Quelle: STARTSEITE https://example.com/)
//
// Hier wird nur die reine E-Mail-Adresse herausgezogen.
function mailAus(v) {
  const treffer = String(v || '').match(
    /[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,24}/i
  );

  return treffer
    ? treffer[0].toLowerCase()
    : '';
}

const inputItems = $input.all();

const sheetErrors = inputItems.filter(function (item) {
  return item.json && item.json.error;
});

if (sheetErrors.length > 0) {
  const details = sheetErrors
    .map(function (item) {
      return c(
        (
          item.json.error &&
          item.json.error.message
        ) ||
        item.json.error
      );
    })
    .filter(Boolean)
    .join(' | ')
    .slice(0, 5000);

  return [{
    json: {
      _hat_kandidat: false,
      _vorbereitungsfehler: true,
      _fehlerdetails:
        'Google Sheet lesen fehlgeschlagen: ' +
        details,
      _gesamt_gelesen: 0,
      _geeignete_kandidaten_gesamt: 0,
      _test_limit: TEST_LIMIT,
      _test_stellen_id: TEST_STELLEN_ID
    }
  }];
}

const kandidaten = [];

for (const item of inputItems) {
  const row = (item && item.json) || {};

  const stellenId = c(row.stellen_id);

  if (!stellenId) {
    continue;
  }

  // Nur aktiv, wenn ausdrücklich eine Test-ID gesetzt ist.
  if (
    TEST_STELLEN_ID !== '' &&
    stellenId !== TEST_STELLEN_ID
  ) {
    continue;
  }

  if (
    c(row.quelle).toLowerCase() !==
    'agentursuche'
  ) {
    continue;
  }

  if (
    c(row.record_type).toUpperCase() !==
    'COMPANY'
  ) {
    continue;
  }

  if (!wahr(row._ist_initiativ)) {
    continue;
  }

  if (!['SEHR_GUT', 'GEEIGNET', 'BEDINGT_GEEIGNET'].includes(c(row.m2_status).toUpperCase())) continue;
  if (!wahr(row._weitergabe_an_m3)) continue;
  if (!wahr(row._weitergabe_an_m3ki)) continue;
  if (c(row.m3ki_status).toUpperCase() === 'FERTIG') continue;

  // Entscheidend ist der gemeinsame M3-Vertrag.
  // Solange m3_status nicht FERTIG ist,
  // muss der Datensatz durch M3KI laufen.
  if (
    c(row.m3_status).toUpperCase() ===
    'FERTIG'
  ) {
    continue;
  }

  kandidaten.push(row);
}

const gewaehlt =
  TEST_LIMIT > 0
    ? kandidaten.slice(0, TEST_LIMIT)
    : kandidaten;

if (gewaehlt.length === 0) {
  return [{
    json: {
      _hat_kandidat: false,
      _vorbereitungsfehler: false,
      _fehlerdetails: '',
      _gesamt_gelesen: inputItems.length,
      _geeignete_kandidaten_gesamt:
        kandidaten.length,
      _test_limit: TEST_LIMIT,
      _test_stellen_id: TEST_STELLEN_ID
    }
  }];
}

return gewaehlt.map(function (row) {
  // Reihenfolge der Versandadresse:
  //
  // 1. bereits vorhandenes gemeinsames Vertragsfeld
  // 2. dedizierte Bewerbungs-/Karriereadresse aus M3B
  // 3. offizielle Kontaktadresse aus M3B
  //
  // Eine offizielle Kontaktadresse ist bei einer
  // Initiativbewerbung eine gültige Versandadresse.

  const bestandMail =
    mailAus(row.bewerbungs_email);

  const m3bBewerbung =
    mailAus(row.m3b_bewerbungs_email);

  const m3bKontakt =
    mailAus(row.m3b_kontakt_email);

  const mailAusBestand =
    bestandMail ||
    m3bBewerbung ||
    m3bKontakt;

  const bestandFirma =
    c(row.firmenbeschreibung);

  const m3bLeistungen =
    c(row.m3b_leistungen);

  const m3bTech =
    c(row.m3b_technologien);

  const fehlt = [];

  if (!mailAusBestand) {
    fehlt.push('bewerbungs_email');
  }

  if (
    !bestandFirma &&
    !m3bLeistungen
  ) {
    fehlt.push('firmenbeschreibung');
  }

  const kiNoetig =
    fehlt.length > 0;

  const prompt = kiNoetig
    ? `
Du recherchierst fehlende Informationen fuer eine INITIATIVBEWERBUNG bei einer Agentur.

Es gibt KEINE Stellenanzeige.
Nutze zwingend die Websuche.
Recherchiere ausschliesslich auf offiziellen Seiten dieses Unternehmens.

UNTERNEHMEN

Firma: ${clip(row.firma, 300)}
Webseite: ${clip(
  row.m3b_website || row.url,
  500
)}
Impressum: ${clip(
  row.m3b_impressum_url,
  500
)}
Kontaktseite: ${clip(
  row.m3b_kontakt_url,
  500
)}
Sitz: ${clip(
  row.m3b_anschrift || row.ort,
  300
)}

BEREITS BELEGT - NICHT AENDERN, NICHT WIEDERHOLEN

Leistungen:
${clip(m3bLeistungen, 1200)}

Technologien:
${clip(m3bTech, 500)}

Referenzen:
${clip(
  row.m3b_projekte_referenzen,
  800
)}

Bekannte Quellen:
${clip(row.m3b_quellen, 2000)}

OFFENE PUNKTE AUS DER VORRECHERCHE

${clip(row.m3b_offene_punkte, 2000)}

FEHLENDE FELDER, DIE DU FUELLEN SOLLST

${fehlt.join(', ')}

REGELN

- Fuelle ausschliesslich die oben genannten fehlenden Felder.
- bewerbungs_email: Bevorzuge eine ausdrueckliche Bewerbungs-, Karriere-, Recruiting- oder Personaladresse.
- Falls keine solche Adresse existiert, darf eine offizielle Kontaktadresse des Unternehmens verwendet werden, zum Beispiel info@, kontakt@, hello@ oder office@.
- Die Adresse muss auf einer offiziellen Seite dieses Unternehmens sichtbar belegt sein.
- Eine Adresse niemals raten und niemals aus der Domain konstruieren.
- firmenbeschreibung: hoechstens 300 Zeichen und maximal 2 Saetze.
- Suche keine Ansprechpartner und keine Anrede.
- Erfinde keine Aufgaben, Anforderungen oder Arbeitgeberleistungen.
- Jobboersen, soziale Netzwerke, Bewertungsportale und Branchenverzeichnisse sind keine gueltigen Quellen.
- Kann ein Wert nicht sicher belegt werden, gib einen leeren String zurueck.
- quellen enthaelt maximal 5 direkte offizielle URLs, auf denen die Angaben tatsaechlich stehen.

ANTWORTE AUSSCHLIESSLICH MIT DIESEM JSON-OBJEKT.
Beginne mit { und ende mit }.
Kein Markdown.

{
  "quellen": [],
  "bewerbungs_email": "",
  "firmenbeschreibung": "",
  "notiz": ""
}
`.trim()
    : '';

  return {
    json: Object.assign({}, row, {
      _hat_kandidat: true,

      _ki_noetig:
        kiNoetig,

      _fehlende_felder:
        fehlt,

      _bestand_mail:
        mailAusBestand,

      _bestand_firmenbeschreibung:
        bestandFirma,

      _m3b_leistungen:
        m3bLeistungen,

      _m3b_tech:
        m3bTech,

      _m3ki_prompt:
        prompt,

      _test_limit:
        TEST_LIMIT,

      _test_stellen_id:
        TEST_STELLEN_ID,

      _geeignete_kandidaten_gesamt:
        kandidaten.length,

      _ki_call:
        0,

      _ki_erfolg:
        false,

      _quellen_gefunden:
        0
    })
  };
});

// Wertet die KI-Antwort aus.
//
// SCHUTZREGELN:
// 1. Vorhandene Werte aus M1/M2/M3B werden niemals überschrieben.
// 2. Eine offizielle Kontaktadresse ist bei Initiativbewerbungen
//    eine gültige Versandadresse.
// 3. Bewerbungs-/Karriereadressen werden bevorzugt.
// 4. Adressen werden niemals geraten oder konstruiert.

function c(v) {
  return String(
    v === null || v === undefined ? '' : v
  )
    .replace(/\u00a0/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function clip(v, n) {
  return c(v).slice(0, n);
}

function fehlerText(e) {
  if (!e) return '';

  if (typeof e === 'string') {
    return c(e).slice(0, 1000);
  }

  return c(
    e.message ||
    e.description ||
    (e.cause && e.cause.message) ||
    JSON.stringify(e)
  ).slice(0, 1000);
}

function textAus(row) {
  const gesammelt = [];

  function add(v) {
    if (
      v === undefined ||
      v === null ||
      v === ''
    ) {
      return;
    }

    if (typeof v === 'string') {
      const text = v.trim();

      if (text) {
        gesammelt.push(text);
      }

      return;
    }

    if (Array.isArray(v)) {
      for (const eintrag of v) {
        add(eintrag);
      }

      return;
    }

    if (typeof v !== 'object') {
      return;
    }

    if (typeof v.output_text === 'string') {
      add(v.output_text);
    }

    if (typeof v.text === 'string') {
      add(v.text);
    }

    if (Array.isArray(v.content)) {
      for (const eintrag of v.content) {
        if (
          eintrag &&
          typeof eintrag.text === 'string'
        ) {
          add(eintrag.text);
        }
      }
    }

    if (Array.isArray(v.output)) {
      for (const eintrag of v.output) {
        add(eintrag);
      }
    }

    if (v.message) add(v.message);
    if (v.response) add(v.response);
    if (v.data) add(v.data);
  }

  add(row && row.output_text);
  add(row && row.output);
  add(row && row.response);
  add(row && row.data);
  add(row && row.content);
  add(row && row.text);

  if (
    row &&
    row.choices &&
    row.choices[0] &&
    row.choices[0].message
  ) {
    add(row.choices[0].message.content);
  }

  if (!gesammelt.length) {
    return null;
  }

  const jsonLike = gesammelt.find(function (wert) {
    return (
      wert.indexOf('{') !== -1 &&
      wert.indexOf('}') !== -1 &&
      /"bewerbungs_email"|"firmenbeschreibung"|"quellen"/i.test(wert)
    );
  });

  return (
    jsonLike ||
    gesammelt[gesammelt.length - 1]
  );
}

function parseJson(v) {
  if (
    v &&
    typeof v === 'object' &&
    !Array.isArray(v)
  ) {
    return v;
  }

  if (typeof v !== 'string') {
    return null;
  }

  const text = v
    .trim()
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();

  function versuch(x) {
    if (!x) return null;

    try {
      return JSON.parse(
        x.replace(/,\s*([}\]])/g, '$1')
      );
    } catch (error) {
      return null;
    }
  }

  const direkt = versuch(text);

  if (direkt) {
    return direkt;
  }

  const anfang = text.indexOf('{');
  const ende = text.lastIndexOf('}');

  if (
    anfang >= 0 &&
    ende > anfang
  ) {
    return versuch(
      text.slice(anfang, ende + 1)
    );
  }

  return null;
}

const BLOCK_DOMAINS = [
  'arbeitsagentur.de',
  'arbeitnow.com',
  'jooble.org',
  'remotive.com',
  'indeed.com',
  'indeed.de',
  'stepstone.de',
  'linkedin.com',
  'xing.com',
  'glassdoor.de',
  'glassdoor.com',
  'kununu.com',
  'heyjobs.co',
  'talent.com',
  'adzuna.de',
  'stellenanzeigen.de',
  'meinestadt.de',
  'jobware.de',
  'monster.de',
  'facebook.com',
  'instagram.com',
  'tiktok.com',
  'youtube.com',
  'twitter.com',
  'x.com',
  'google.com',
  'google.de',
  'bing.com'
];

function normUrl(v) {
  let roh = c(v)
    .replace(/^[<({\[]+/, '')
    .replace(/[>)}\],;]+$/, '');

  if (/^www\./i.test(roh)) {
    roh = 'https://' + roh;
  }

  return /^https?:\/\/[^\s]+$/i.test(roh)
    ? roh
    : '';
}

function istBlockiert(v) {
  const match = normUrl(v).match(
    /^https?:\/\/([^\/?#]+)/i
  );

  const domain = match
    ? match[1]
        .toLowerCase()
        .replace(/^www\./, '')
    : '';

  return (
    !domain ||
    BLOCK_DOMAINS.some(function (blockiert) {
      return (
        domain === blockiert ||
        domain.endsWith('.' + blockiert)
      );
    })
  );
}

function hostAus(v) {
  const match = normUrl(v).match(/^https?:\/\/([^\/?#]+)/i);
  return match ? match[1].toLowerCase().replace(/^www\./, '') : '';
}

function istFirmenDomain(host, firmaHost) {
  return Boolean(host && firmaHost && (host === firmaHost || host.endsWith('.' + firmaHost)));
}

function offizielleUrls(vals, firmaHost) {
  const gesehen = new Set();
  const ergebnis = [];

  for (const wert of vals || []) {
    const url = normUrl(wert);

    if (
      !url ||
      istBlockiert(url) ||
      !istFirmenDomain(hostAus(url), firmaHost)
    ) {
      continue;
    }

    const schluessel =
      url.toLowerCase();

    if (gesehen.has(schluessel)) {
      continue;
    }

    gesehen.add(schluessel);
    ergebnis.push(url);
  }

  return ergebnis;
}

function quellenAnhaengen(
  bestand,
  neueQuellen
) {
  const aktuell = String(bestand || '')
    .split('|')
    .map(c)
    .filter(Boolean);

  for (const quelle of neueQuellen) {
    const vorhanden = aktuell.some(
      function (eintrag) {
        return (
          eintrag.toLowerCase() ===
          quelle.toLowerCase()
        );
      }
    );

    if (!vorhanden) {
      aktuell.push(quelle);
    }
  }

  return aktuell
    .join(' | ')
    .slice(0, 10000);
}

const MAIL_BLOCK =
  /^(noreply|no-reply|donotreply|do-not-reply|mailer-daemon|abuse|datenschutz|privacy|dpo|webmaster|hostmaster|postmaster|admin)$/i;

const FREEMAIL = new Set([
  'gmail.com',
  'googlemail.com',
  'gmx.de',
  'gmx.net',
  'web.de',
  'outlook.com',
  'hotmail.com',
  'hotmail.de',
  'yahoo.com',
  'yahoo.de',
  't-online.de',
  'freenet.de',
  'aol.com',
  'icloud.com',
  'mail.com'
]);

function mailRang(email) {
  const lokal =
    String(email).split('@')[0].toLowerCase();

  // Dedizierte Bewerbungsadresse bevorzugen.
  if (
    /(bewerbung|bewerbungen|karriere|career|careers|jobs?|recruit|recruiting|talent|personal|hr|humanresources|people|workwithus)/i.test(lokal)
  ) {
    return 100;
  }

  // Offizielle allgemeine Kontaktadresse ist gültiger Fallback.
  if (
    /^(info|kontakt|contact|office|hello|hallo|team|mail)$/i.test(lokal)
  ) {
    return 50;
  }

  if (/^support/i.test(lokal)) {
    return 10;
  }

  // Andere belegte Firmenadressen bleiben grundsätzlich zulässig.
  return 30;
}

function mailPruefen(v, firmaHost = '') {
  const treffer =
    String(v || '').match(
      /[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,24}/gi
    ) || [];

  const gueltig = [];

  for (const roh of treffer) {
    const email = roh
      .toLowerCase()
      .trim();

    const teile =
      email.split('@');

    const lokal =
      teile[0] || '';

    const domain =
      teile[1] || '';

    if (
      !lokal ||
      !domain ||
      domain.indexOf('.') === -1
    ) {
      continue;
    }

    if (MAIL_BLOCK.test(lokal)) {
      continue;
    }

    if (
      /^(max\.?mustermann|vorname\.?nachname|name|email|mailadresse|beispiel|example)$/i.test(lokal)
    ) {
      continue;
    }

    if (
      [
        'example.com',
        'example.org',
        'domain.com',
        'email.com'
      ].includes(domain)
    ) {
      continue;
    }

    if (FREEMAIL.has(domain)) {
      continue;
    }

    if (firmaHost && !istFirmenDomain(domain, firmaHost)) {
      continue;
    }

    if (!gueltig.includes(email)) {
      gueltig.push(email);
    }
  }

  return (
    gueltig.sort(function (a, b) {
      return (
        mailRang(b) -
        mailRang(a) ||
        a.localeCompare(b)
      );
    })[0] || ''
  );
}

function firmaPruefen(v) {
  const text = c(v);

  if (
    text.length < 20 ||
    text.split(/\s+/).length < 4
  ) {
    return '';
  }

  return text.slice(0, 1000);
}

return $input.all().map(function (item) {
  const row =
    (item && item.json) || {};

  const heute =
    new Date().toISOString();

  // Bestand aus M1/M2/M3B hat immer Vorrang.
  const bestandMail =
    mailPruefen(row._bestand_mail);

  const bestandFirma =
    c(
      row._bestand_firmenbeschreibung
    );

  const m3bLeistungen =
    c(row._m3b_leistungen);

  const apiFehler =
    fehlerText(row.error);

  const roh =
    textAus(row);

  const parsed =
    apiFehler
      ? null
      : parseJson(roh);

  const firmaHost = hostAus(row.m3b_website || row.url);

  let kiMail = '';
  let kiFirma = '';
  let quellen = [];
  let kiFehler = '';

  if (apiFehler) {
    kiFehler =
      'M3KI-KI-Aufruf fehlgeschlagen: ' +
      apiFehler;
  } else if (!parsed) {
    kiFehler =
      'M3KI-KI-Antwort war kein gueltiges JSON-Objekt.' +
      (
        typeof roh === 'string'
          ? ' Rohantwort: ' +
            clip(roh, 400)
          : ''
      );
  } else {
    quellen = offizielleUrls(
      Array.isArray(parsed.quellen)
        ? parsed.quellen
        : [],
      firmaHost
    ).slice(0, 5);

    const hatOffizielleQuelle =
      quellen.length > 0;

    kiMail = hatOffizielleQuelle
      ? mailPruefen(
          parsed.bewerbungs_email,
          firmaHost
        )
      : '';

    kiFirma = hatOffizielleQuelle
      ? firmaPruefen(
          parsed.firmenbeschreibung
        )
      : '';
  }

  // Bestand gewinnt immer.
  // Die KI darf nur echte Lücken ergänzen.
  const email =
    bestandMail ||
    kiMail;

  const firmenbeschreibung =
    bestandFirma ||
    m3bLeistungen.slice(0, 1000) ||
    kiFirma;

  const offen = [];

  if (!email) {
    offen.push(
      'Keine belegte Bewerbungs- oder Kontakt-E-Mail gefunden.'
    );
  }

  if (!firmenbeschreibung) {
    offen.push(
      'Keine belegbare Firmenbeschreibung gefunden.'
    );
  }

  if (kiFehler) {
    offen.push(
      'KI-Recherche technisch fehlgeschlagen.'
    );
  }

  const contactStatus =
    email
      ? 'EMAIL_GEFUNDEN'
      : 'EMAIL_FEHLT';

  const contentStatus =
    firmenbeschreibung
      ? 'FIRMENPROFIL_KOMPLETT'
      : 'FIRMENPROFIL_UNVOLLSTAENDIG';

  // M3 ist eine Faktenstufe, keine Kontakt-Ablehnung. Fehlende E-Mail oder
  // eine ausgefallene optionale Nachrecherche bleiben sichtbar, blockieren M4
  // aber nicht, solange verwertbare Firmensubstanz vorhanden ist.
  const hatSubstanz = Boolean(
    firmenbeschreibung || c(row.m3a_firmenkern) || c(row.m3a_angebotene_leistungen) ||
    c(row.m3b_leistungen) || c(row.m3b_technologien) || c(row.m3a_technologien)
  );
  const m3Status = hatSubstanz ? 'FERTIG' : 'M3_TECHNISCHER_FEHLER';
  const m3kiStatus = kiFehler ? 'FEHLER' : (email && firmenbeschreibung ? 'FERTIG' : 'TEILWEISE');

  return {
    json: Object.assign({}, row, {
      bewerbungs_email:
        email,

      firmenbeschreibung:
        firmenbeschreibung,

      m3_quellen:
        quellenAnhaengen(
          row.m3_quellen,
          quellen
        ),

      m3_status:
        m3Status,

      // Sichtbarer Hinweis fuer die manuelle Pruefliste. Eine Firma ohne
      // Bewerbungsadresse ist nicht erledigt, sie braucht einen Menschen.
      m3_fehlergrund:
        !hatSubstanz
          ? 'Keine verwertbare Firmensubstanz - technisch pruefen'
          : !email
            ? 'E-Mail fehlt - vor Versand manuell pruefen'
            : kiFehler
              ? 'Optionale M3KI-Nachrecherche fehlgeschlagen - vorhandene Fakten an M4 uebergeben'
              : '',

      contact_status:
        contactStatus,

      content_status:
        contentStatus,

      m3ki_status:
        m3kiStatus,

      m3ki_quellen:
        quellen.join(' | '),

      m3ki_offene_punkte:
        offen.length
          ? offen
              .map(function (
                punkt,
                index
              ) {
                return (
                  index +
                  1 +
                  '. ' +
                  punkt
                );
              })
              .join(' | ')
          : 'Keine offenen Punkte.',

      m3ki_fehler:
        kiFehler,

      m3ki_bearbeitet_am:
        heute,

      _ki_call:
        1,

      _ki_erfolg:
        !kiFehler,

      _quellen_gefunden:
        quellen.length,

      _email_aus_ki:
        !bestandMail &&
        Boolean(kiMail),

      _firmenbeschreibung_aus_ki:
        !bestandFirma &&
        !m3bLeistungen &&
        Boolean(kiFirma)
    })
  };
});

// Alles bereits aus M1/M2/M3B belegt - kein KI-Aufruf noetig.
function c(v) { return String(v === null || v === undefined ? '' : v).replace(/\s+/g, ' ').trim(); }

return $input.all().map(function (item) {
  const row = (item && item.json) || {};
  const heute = new Date().toISOString();

  const email = c(row._bestand_mail).toLowerCase();
  const firmenbeschreibung = c(row._bestand_firmenbeschreibung) || c(row._m3b_leistungen).slice(0, 1000);

  return { json: Object.assign({}, row, {
    bewerbungs_email: email,
    firmenbeschreibung: firmenbeschreibung,
    m3_quellen: c(row.m3_quellen),
    m3_status: 'FERTIG',
    contact_status: email ? 'EMAIL_GEFUNDEN' : 'EMAIL_FEHLT',
    content_status: firmenbeschreibung ? 'FIRMENPROFIL_KOMPLETT' : 'FIRMENPROFIL_UNVOLLSTAENDIG',
    m3ki_status: 'FERTIG',
    m3ki_quellen: '',
    m3ki_offene_punkte: 'Keine offenen Punkte. Alle Angaben stammen aus M3B, kein KI-Aufruf noetig.',
    m3ki_fehler: '',
    m3ki_bearbeitet_am: heute,
    _ki_call: 0, _ki_erfolg: false, _quellen_gefunden: 0,
    _email_aus_ki: false, _firmenbeschreibung_aus_ki: false
  }) };
});

// Reduziert auf stellen_id + M3-Vertragsfelder + m3ki_*-Steuerfelder.
// konkrete_aufgabe, konkrete_anforderung, angebot_an_bewerber, ansprechpartner und
// ansprache werden BEWUSST NICHT geschrieben - bei Initiativbewerbungen gibt es sie nicht
// bzw. sie werden nicht recherchiert. Alle uebrigen Spalten bleiben unberuehrt.
function t(v, n) {
  return String(v === null || v === undefined ? '' : v).replace(/\s+/g, ' ').trim().slice(0, n || 8000);
}

return $input.all().map(function (item) {
  const r = (item && item.json) || {};
  return { json: {
    stellen_id: t(r.stellen_id, 500),
    bewerbungs_email: t(r.bewerbungs_email, 500).toLowerCase(),
    firmenbeschreibung: t(r.firmenbeschreibung, 5000),
    m3_quellen: t(r.m3_quellen, 10000),
    m3_status: t(r.m3_status, 100),
    contact_status: t(r.contact_status, 100),
    content_status: t(r.content_status, 100),
    m3ki_status: t(r.m3ki_status, 20),
    m3ki_quellen: t(r.m3ki_quellen, 8000),
    m3ki_offene_punkte: t(r.m3ki_offene_punkte, 4000),
    m3ki_fehler: t(r.m3ki_fehler, 2000),
    m3ki_bearbeitet_am: t(r.m3ki_bearbeitet_am, 40)
  } };
});

function c(v) { return String(v === null || v === undefined ? '' : v).replace(/\s+/g, ' ').trim(); }

let final = [], formatiert = [];
try { final = $('M3KI-Pfade zusammenführen1').all(); } catch (e) {}
try { formatiert = $('Exaktes Standardformat M3KI1').all(); } catch (e) {}

const sheetItems = $input.all();
const sheetErrors = sheetItems.filter(function (i) { return i.json && i.json.error; });

function zaehle(s) { return formatiert.filter(function (i) { return c(i.json.m3ki_status) === s; }).length; }
function summe(f) { return final.reduce(function (t, i) { return t + Number((i.json || {})[f] || 0); }, 0); }

let status = 'ERFOLGREICH';
if (sheetErrors.length) status = 'SHEET_SCHREIBFEHLER';
else if (zaehle('FEHLER')) status = 'ERFOLGREICH_MIT_FEHLERN';

const firmen = formatiert.map(function (i) {
  const j = i.json;
  return {
    stellen_id: c(j.stellen_id),
    m3ki_status: c(j.m3ki_status),
    m3_status: c(j.m3_status),
    bewerbungs_email: c(j.bewerbungs_email),
    contact_status: c(j.contact_status),
    content_status: c(j.content_status),
    offene_punkte: c(j.m3ki_offene_punkte)
  };
});

const first = (final[0] && final[0].json) || {};

return [{ json: {
  workflow: 'M3KI – Nachrecherche Initiativ',
  status: status,
  quelle: 'Agentursuche',
  test_limit: Number(first._test_limit || 0),
  geeignete_kandidaten_gesamt: Number(first._geeignete_kandidaten_gesamt || formatiert.length),
  verarbeitete_firmen: formatiert.length,
  fertig: zaehle('FERTIG'),
  teilweise: zaehle('TEILWEISE'),
  fehler: zaehle('FEHLER'),
  ki_calls: summe('_ki_call'),
  email_aus_ki: final.filter(function (i) { return i.json._email_aus_ki === true; }).length,
  firmenbeschreibung_aus_ki: final.filter(function (i) { return i.json._firmenbeschreibung_aus_ki === true; }).length,
  offizielle_quellen: summe('_quellen_gefunden'),
  sheet_schreibfehler: sheetErrors.length,
  firmen: firmen,
  ausgefuehrt_am: new Date().toISOString()
} }];

const row = $input.first().json ?? {};

if (row._vorbereitungsfehler === true) {
  return [{
    json: {
      workflow: 'M3KI – KI-Recherche',
      status: 'VORBEREITUNGSFEHLER',
      testmodus: row._test_modus === true,
      test_limit: Number(row._test_limit ?? 0),
      offene_stellen_gesamt: 0,
      verarbeitete_stellen: 0,
      fertig: 0,
      kein_email: 0,
      fehler: 0,
      ki_calls: 0,
      http_calls: 0,
      sheet_schreibfehler: 0,
      fehlerdetails: String(row._fehlerdetails ?? '').slice(0, 10000),
      ausgefuehrt_am: new Date().toISOString(),
    },
  }];
}

return [{
  json: {
    workflow: 'M3KI – KI-Recherche',
    status: 'ERFOLGREICH_KEINE_OFFENEN_STELLEN',
    testmodus: row._test_modus === true,
    test_limit: Number(row._test_limit ?? 0),
    gesamt_gelesen: Number(row._gesamt_gelesen ?? 0),
    offene_stellen_gesamt: Number(row._geeignete_kandidaten_gesamt ?? 0),
    verarbeitete_stellen: 0,
    fertig: 0,
    kein_email: 0,
    fehler: 0,
    ki_calls: 0,
    http_calls: 0,
    ohne_row_number: Number(row._ohne_row_number ?? 0),
    ohne_stellen_id: Number(row._ohne_stellen_id ?? 0),
    sheet_schreibfehler: 0,
    fehlerdetails: '',
    ausgefuehrt_am: new Date().toISOString(),
  },
}];
